"""
Regenerates docs/USER_GUIDE.md from backend/app/services/guide.json, the single source of the use guide (the quorum_guide chat tool, GET
/api/guide and the console panel read the same file). A backend test fails if the committed Markdown is out of date.

    python scripts/gen_guide_md.py
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def render(g: dict) -> str:
    out = [
        "# Using Quorum",
        "",
        "<!-- Generated by scripts/gen_guide_md.py from backend/app/services/guide.json. Edit that file, not this one. -->",
        "",
        g["intro"],
        "",
        "You never need the console for any of this: every step below is something you ask your AI to do. Inside the chat, `quorum_guide` returns the same text, one topic at a time.",
        "",
        "| Topic | What it covers |",
        "| --- | --- |",
    ]
    out += [f"| [{t['title']}](#{t['id']}) | {t['summary']} |" for t in g["topics"]]
    out += ["| [Teach your AI how to use it](#install) | The working agreement and hooks |", ""]
    for t in g["topics"]:
        out += [f'<a id="{t["id"]}"></a>', f"## {t['title']}", "", t["summary"], ""]
        out += [f"{i}. {s}" for i, s in enumerate(t["steps"], 1)]
        if t.get("say"):
            out += ["", "Things to say to your AI: " + "; ".join(f"\"{s}\"" for s in t["say"])]
        if t.get("tools"):
            out += ["", "Tools: " + ", ".join(f"`{x}`" for x in t["tools"])]
        out.append("")
    out += ['<a id="install"></a>', "## Teach your AI how to use it", "",
            "Ask your AI to call `quorum_guide(topic='install', client='<your AI>')`. It adds this working agreement to the right file for that AI, so every future session follows it:", ""]
    out += [f"{i}. {r}" for i, r in enumerate(g["rules"], 1)]
    out += ["", "Where it goes, per AI:", "", "| AI | File | Note |", "| --- | --- | --- |"]
    out += [f"| {k} | {v['file']} | {v['note'] or ' '} |" for k, v in g["clients"].items()]
    out += ["", "For Claude Code there are two optional hooks:", "", f"- **Capture.** {g['hooks']['capture']}", f"- **Collision warnings.** {g['hooks']['conflict']}", f"- {g['hooks']['token']}", ""]
    return "\n".join(out)


def main() -> int:
    g = json.loads((ROOT / "backend" / "app" / "services" / "guide.json").read_text(encoding="utf8"))
    target = ROOT / "docs" / "USER_GUIDE.md"
    target.write_bytes((render(g)).encode("utf8"))
    print(f"Updated {target}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
